INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p588158-mine399', 'stk-user4854', 'MINE 399', 'info', '{"desc": "شوف نصيحه لا تخلص الكواب الا وانت مخلص الربورت عشان ما يشغلك ويبهذلك وقت الدراسه زي انا\n\nوحاول قد ماتقدر ما تطلع من الشركه الا وانت ماخذ كل السورسات الي تقدر عليها\n\nوالتقرير سهالات اغلبه كوبي بيست من المانيوال حق الشركه والكيس ستدي اهتم فيها لانه راح يكون اغلب الاسئله في البرزنتيشن عليها\n\nو الامر المهم انك تضبط الرئيس حقك في الشركه بخصوص التقيم لانه 25 من مائه حاول تشرح له الوضع انك\n\nتحتاجها من هالكلام\n\nاي سؤال اخر احنا مستعدين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/all-about-coop/86785/11", "user": "user4854", "ts": 1270993989000, "tid": 86785, "pn": 11}}', 1270993989000, 1794831603, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1426093-mine399', 'stk-eng2008rt', 'MINE 399', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته … لاتقلق مازال أمامك متسع من الوقت بإذن الله\n\nمبدئياً فيه اجراءات معينة لازم تسويها من قسمك الأكاديمي حتى يتأكدون انك مستوفي الشروط من معدل وبعض المواد اللازمة قبل التطبيق\n\nاذا اخذت الموافقه منهم فيه اوراق توديها لقسم التدريب ويكملون أوراقك ويعطونك خطاب موجه للشركات الي تبي تقدم عليها\n\nهالإجراءات راح تبين مع الوقت وراح تجيك ايميلات فيها تفاصيل كاملة بالي لك والي عليك\n\nلكن اذا متأكد انك مستوفي الشروط فممكن تستبق الأحداث وتجهز لك cv وتزور الشركات الي تناسب تخصصك شخصياً وتقدم عليهم عاادي\n\nودائماً قسم التدريب بمبنى 68 والكوواب كوردنيتور في قسمك الأكاديمي مستعدين يجاوبوك على اسئلتك أياً كانت\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/152-153/169687/2", "user": "Eng2008RT", "ts": 1440721113000, "tid": 169687, "pn": 2}}', 1440721113000, 1794831603, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
